package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotModeDecision.Posture.*;
import static net.battlespades.bot.BotModePolicies.*;
import static net.battlespades.bot.BotVectors.*;

/** Objective selection from detached, mode-sanctioned community-mode facts. */
public final class BotUnofficialPolicy {
    private BotUnofficialPolicy(){}
    @SuppressWarnings("unchecked") static Map<String,Object> map(Object v){return (Map<String,Object>)v;}
    static List<?> list(Map<String,Object> f,String key){return (List<?>)f.getOrDefault(key,List.of());}
    static int integer(Map<String,Object> f,String key,int fallback){var v=f.get(key);return v instanceof Number n?n.intValue():fallback;}
    static double number(Map<String,Object> f,String key,double fallback){var v=f.get(key);return v instanceof Number n?n.doubleValue():fallback;}
    static boolean flag(Map<String,Object> f,String key){return Boolean.TRUE.equals(f.get(key));}
    static Vector vector(Object o){if(o instanceof Vector v)return v;var a=(List<?>)o;return new Vector(((Number)a.get(0)).doubleValue(),((Number)a.get(1)).doubleValue(),((Number)a.get(2)).doubleValue());}
    static Vector at(Map<String,Object> f,String key){return vector(f.getOrDefault(key,List.of(0,0,0)));}
    static Vector home(List<?> homes,int team,Vector fallback){for(var o:homes){var a=(List<?>)o;if(((Number)a.get(0)).intValue()==team)return vector(a.get(1));}return fallback;}
    static Vector nearestPoint(List<?> points,Vector p){return points.stream().map(BotUnofficialPolicy::vector).min(Comparator.comparingDouble(v->distance(p,v))).orElseThrow();}
    static BotModeDecision goal(Vector p,String role,String directive,double radius,double combat){return d(p,"fun_"+role,true,radius,directive,combat>=60?ASSAULT:DEFEND,1,combat);}
    static BotModeDecision goal(Vector p,String role,double combat){return goal(p,role,"",2,combat);}
    public static BotModeDecision decide(Perception frame,Player observer){var f=frame.fun();String code=frame.mode();int team=observer.team(),pid=observer.id();var center=at(f,"center");var homes=list(f,"homes");var home=home(homes,team,center);Vector enemy=center;for(var o:homes){var row=(List<?>)o;if(((Number)row.get(0)).intValue()!=team){enemy=vector(row.get(1));break;}}Map<String,Object> mine=null;for(var o:list(f,"players")){var p=map(o);if(integer(p,"player_id",-1)==pid){mine=p;break;}}if(mine==null||!flag(mine,"active")||flag(mine,"prisoner")||flag(f,"paused"))return goal(observer.position(),"wait_round","hold",2,0);
        if(!frame.modePhase().equals("live")){if(!frame.modePhase().equals("prepare"))return goal(observer.position(),"wait_round","hold",2,0);if(code.equals("false_wall")){if(!list(f,"stashed").stream().anyMatch(v->((Number)v).intValue()==team))return goal(new Vector(home.x(),home.y()+8,home.z()),"stash_cache","stash",1,18);return goal(home,"build_false_wall","fortify",2,18);}if(Set.of("towerfall","scrapyard_engineers").contains(code))return goal(home,"fortify_core","fortify",2,18);if(!code.equals("block_hunt")||team==integer(f,"attackers",-1))return goal(observer.position(),"wait_start","hold",2,0);}
        var hunt=list(f,"hunt_points");if(code.equals("block_hunt")){if(team!=integer(f,"attackers",-1)){if(!hunt.isEmpty())return goal(vector(hunt.get(Math.floorMod(pid,hunt.size()))),"hide_as_block","hide",1,0);int sign=pid%2!=0?-1:1;return goal(new Vector(home.x()+(Math.floorMod(pid,3)-1)*7,home.y()+sign*22,home.z()),"hide_as_block","hide",1,0);}var clues=list(f,"clues");if(frame.createdAt()<number(f,"clue_until",0)&&!clues.isEmpty())return goal(nearestPoint(clues,observer.position()),"investigate_clue",90);if(!hunt.isEmpty())return goal(vector(hunt.get(Math.floorMod((int)(frame.createdAt()/30)+pid,hunt.size()))),"search_props",90);int step=Math.floorMod((int)(frame.createdAt()/8)+pid*3,12);return goal(new Vector(center.x()+(step%4-1.5)*24,center.y()+(step/4-1)*24,center.z()),"search_props",90);}
        if(Set.of("crumbling_run","red_light_raid").contains(code)){if(code.equals("red_light_raid")&&(flag(f,"red")||number(f,"light_remaining",0)<.8))return goal(observer.position(),"red_light_stop","hold",2,0);var checkpoints=list(f,"checkpoints");int index=Math.min(integer(mine,"checkpoint",0)+1,checkpoints.size()-1);return goal(vector(checkpoints.get(index)),"ordered_checkpoints","race",.8,0);}
        if(code.equals("floor_tax"))return goal(observer.position(),"keep_safe_floor","floor",.5,0);if(code.equals("hot_potato"))return goal(observer.position(),integer(f,"holder",-1)==pid?"pass_curse":"evade_curse","tag",.5,0);if(Set.of("one_in_the_spade","borrowed_arsenal").contains(code)){int step=Math.floorMod((int)(frame.createdAt()/7)+pid,8);return goal(new Vector(center.x()+Math.cos(step*Math.PI/4)*27,center.y()+Math.sin(step*Math.PI/4)*27,center.z()),"free_for_all",100);}
        if(code.equals("lockdown")){for(var o:list(f,"players")){var p=map(o);if(flag(p,"prisoner")&&frame.players().stream().anyMatch(q->q.id()==integer(p,"player_id",-1)&&q.team()==team))return goal(enemy,"rescue_prisoners","",3,9);}return goal(pid%3!=0?enemy:home,"capture_or_guard",70);}
        if(code.equals("kingmaker"))return goal(new Vector(center.x()+Math.cos(pid*2.4)*4,center.y()+Math.sin(pid*2.4)*4,center.z()),"hold_hill",18);
        if(code.equals("paint_raid")){var b=list(f,"paint_bounds");int x0=((Number)b.get(0)).intValue(),x1=((Number)b.get(1)).intValue(),y0=((Number)b.get(2)).intValue(),y1=((Number)b.get(3)).intValue();double z=((Number)b.get(4)).doubleValue();int row=Math.floorMod(pid*5+(int)(frame.createdAt()/12)*3,y1-y0+1),x=((int)(frame.createdAt()/6))%2!=0?x0+2:x1-2;return goal(new Vector(x,y0+row+.5,z-2.25),"paint_territory","paint",1,8);}
        if(Set.of("towerfall","scrapyard_engineers").contains(code)){if(code.equals("scrapyard_engineers")&&observer.blocks()<20)return goal(center,"refill_scrap","",2,8);Vector core=null;for(var o:list(f,"cores")){var row=(List<?>)o;if(((Number)row.get(0)).intValue()!=team){core=vector(row.get(1));break;}}return goal(core==null?enemy:core,"destroy_core","demolish",2,18);}
        if(code.equals("night_shift")){int stage=integer(f,"stage",0);if(team!=constantTeam1())return goal(stage==3?at(f,"exit"):home(homes,constantTeam1(),center),"pressure_outpost",90);var repair=list(f,"repair_cells");if(stage==1&&!repair.isEmpty())return goal(nearestPoint(repair,observer.position()),"repair_barricade","repair",2,10);if(stage==3)return goal(at(f,"exit"),"hold_evacuation","",3,10);}
        var cargo=list(f,"cargo").stream().map(BotUnofficialPolicy::map).toList();var carried=cargo.stream().filter(c->integer(c,"holder",-1)==pid).findFirst().orElse(null);if(carried!=null){if(code.equals("last_exit"))return goal(flag(f,"exit_open")?at(f,"exit"):home,flag(f,"exit_open")?"extract_loot":"protect_loot","",2,9);return goal(Set.of("bridge_chicken","smugglers_run","reverse_siege","spadeball").contains(code)?enemy:home,code.equals("spadeball")?"deliver_ball":"deliver_cargo","",2,5);}
        if(Set.of("smugglers_run","reverse_siege").contains(code)&&team!=integer(f,"attackers",-1))return goal(home,"intercept_smugglers","",3,40);
        var available=cargo.stream().filter(c->integer(c,"holder",-1)<0&&flag(c,"ready")&&(!code.equals("false_wall")||integer(c,"team",-1)!=team)&&(!code.equals("bridge_chicken")||integer(c,"team",-1)==team)).min(Comparator.comparingDouble(c->distance(observer.position(),at(c,"position"))/Math.max(1,integer(c,"value",1)))).orElse(null);if(available!=null)return goal(at(available,"position"),code.equals("spadeball")?"collect_ball":"collect_cargo","",1.2,9);if(code.equals("last_exit")&&flag(f,"exit_open"))return goal(at(f,"exit"),"extract","",2,9);var visible=cargo.stream().filter(c->integer(c,"holder",-1)>=0&&!flag(c,"hidden")).min(Comparator.comparingDouble(c->distance(observer.position(),at(c,"position")))).orElse(null);if(visible!=null)return goal(at(visible,"position"),"escort_or_intercept_carrier","",4,20);return goal(center,"contest_objective",30);
    }
    private static int constantTeam1(){return Math.toIntExact(net.battlespades.catalog.SourceCatalog.load("bot-modes").getLong("team1"));}
}
